pub fn trace(&self) -> T 
where
    T: Field + Scalar,
{
    let (m, n) = self.dim();
    debug_assert_eq!(m, n, "Trace can only be calculated for square matrices");

    let mut sum = T::zero();
    for i in 0..m {
        sum = sum + self[[i, i]];
    }
    sum
}

